        "statement": "For distinct nonzero integer anchors a,b and a common rational neighbor u/v in lowest terms, at every odd prime p with v_p(v)>max(v_p(a),v_p(b)), the ratio of the p-free parts of a and b is a quadratic residue modulo p.",
        "assumptions": [
          "a,b are distinct nonzero integers.",
          "u/v is reduced with v>0.",
          "au/v+1 and bu/v+1 are rational squares.",
          "p is odd and v_p(v)>max(v_p(a),v_p(b))."
        ],
        "quantifiers": [
          "For all such a,b,u/v and p."
        ],
        "objective": "proof"
      }
    ],
